function dashboardActivate(name, p) { requireStaff(); p = p || {};
  const d = String(p.payDate || '').match(/^(\d{4})-(\d{2})-(\d{2})$/); if (!d) throw new Error('חסר תאריך תשלום');
  if (!(Number(p.months) > 0)) throw new Error('חסר לכמה חודשים');
  const startTxt = d[3] + '/' + d[2] + '/' + d[1];
  onbSavePay(name, p);
  const c = clientRow(name); c.sh.getRange(c.row, C['תחילת תהליך']).setValue(startTxt); SpreadsheetApp.flush();
  const log = setupClient(name);
  const c2 = clientRow(name);
  try { if (c2.fileId) { SpreadsheetApp.openById(c2.fileId).getSheetByName('שקילות יומיות').getRange('B3').setValue(startTxt); try { fitTrackingWeeks_(c2.fileId, c2); } catch (e) {} } } catch (e) {}
  try { CacheService.getScriptCache().removeAll(['onb', 'pulse']); } catch (e) {}
  return { log, start: startTxt, trackUrl: c2.fileId ? 'https://docs.google.com/spreadsheets/d/' + c2.fileId + '/edit' : '', folderUrl: c2.folderId ? 'https://drive.google.com/drive/folders/' + c2.folderId : '' }; }

